package fraymus.workspace;
import org.junit.Test;
import static org.junit.Assert.*;
import java.awt.Color;
import java.nio.file.*;
import java.util.*;
import org.json.*;

public class VisualMemory043Test {
    static JSONObject source(String session,long sequence,String kind,String artifact,int version){return new JSONObject().put("kind",kind).put("sessionId",session).put("sequence",sequence).put("elapsedMs",sequence*10).put("url","http://127.0.0.1/labelled-unit-control").put("title","Labelled unit image, not physical footage").put("viewport",new JSONArray(new int[]{200,120})).put("artifactId",artifact).put("artifactVersion",version);}
    static JSONObject put(VisualMemory043 memory,String task,String effect,String session,long n,String phase,int shift,Color color,String artifact,int version)throws Exception{return memory.retain(task,effect,session,phase,source(session,n,"canvas",artifact,version),Base64.getEncoder().encodeToString(ScreenPixels043Test.png(ScreenPixels043Test.image(shift,color))));}
    static JSONObject artifact(String id,int version,boolean passed){return new JSONObject().put("id",id).put("version",version).put("test",new JSONObject().put("version",version).put("passed",passed).put("checks",new JSONArray().put(new JSONObject().put("passed",passed))));}
    @Test public void originalsHaveExactHashesAndChangedBytesAreNeverSilentlyReplaced()throws Exception{Path root=Files.createTempDirectory("visual043-original");var m=new VisualMemory043(root);String task=UUID.randomUUID().toString(),effect=UUID.randomUUID().toString(),session=UUID.randomUUID().toString();var f=put(m,task,effect,session,1,"before",0,Color.BLUE,"",0);assertEquals(f.getString("sha256"),PerceptionStore.hash(m.original(f.getString("id"))));Path file=root.resolve("agency-043/screens/"+f.getString("id")+".png");byte[] bytes=Files.readAllBytes(file);bytes[bytes.length-1]^=1;Files.write(file,bytes);assertThrows(Exception.class,()->new VisualMemory043(root));assertArrayEquals(bytes,Files.readAllBytes(file));}
    @Test public void sourceActionSequenceAndViewportBoundariesAreEnforced()throws Exception{var m=new VisualMemory043(Files.createTempDirectory("visual043-order"));String task=UUID.randomUUID().toString(),effect=UUID.randomUUID().toString(),session=UUID.randomUUID().toString();var a=put(m,task,effect,session,1,"before",0,Color.BLUE,"",0);assertThrows(IllegalArgumentException.class,()->put(m,task,effect,session,1,"after",0,Color.BLUE,"",0));var b=put(m,task,effect,session,2,"after",8,Color.BLUE,"",0);assertTrue(m.pair(a.getString("id"),b.getString("id")).getDouble("changedFraction")>0);var other=put(m,task,UUID.randomUUID().toString(),session,3,"after",8,Color.BLUE,"",0);assertThrows(IllegalStateException.class,()->m.pair(a.getString("id"),other.getString("id")));assertThrows(IllegalArgumentException.class,()->m.retain(task,effect,session,"after",source(session,4,"canvas","",0).put("viewport",new JSONArray("[50,50]")),Base64.getEncoder().encodeToString(ScreenPixels043Test.png(ScreenPixels043Test.image(0,Color.BLUE)))));}
    @Test public void visualRoutineRequiresMatchingTaskVersionAndPassingReceiptThenRetrievesHeldOutLayout()throws Exception{var m=new VisualMemory043(Files.createTempDirectory("visual043-routine"));String task=UUID.randomUUID().toString(),effect=UUID.randomUUID().toString(),session=UUID.randomUUID().toString(),artifact=UUID.randomUUID().toString();var frame=put(m,task,effect,session,1,"after",0,new Color(15,40,60),artifact,1);assertThrows(IllegalStateException.class,()->m.learn(task,frame.getString("id"),artifact(artifact,1,false),null,new JSONArray()));assertThrows(IllegalStateException.class,()->m.learn(task,frame.getString("id"),artifact(artifact,2,true),null,new JSONArray()));var pattern=m.learn(task,frame.getString("id"),artifact(artifact,1,true),new JSONObject().put("name","declared-unit-recipe").put("version",1),new JSONArray());assertEquals(1,m.state().getJSONArray("patterns").length());var held=put(m,UUID.randomUUID().toString(),UUID.randomUUID().toString(),session,2,"after",8,new Color(15,40,60),artifact,1);var matches=m.matches(held.getString("id"));assertEquals(pattern.getString("id"),matches.getJSONObject(0).getString("id"));assertTrue(matches.getJSONObject(0).getDouble("similarity")>.9);assertTrue(matches.getJSONObject(0).getString("meaning").contains("not a calibrated"));}
    @Test public void retainedRoutinesAndSequenceFenceSurviveRestart()throws Exception{Path root=Files.createTempDirectory("visual043-restart");var m=new VisualMemory043(root);String task=UUID.randomUUID().toString(),effect=UUID.randomUUID().toString(),session=UUID.randomUUID().toString(),artifact=UUID.randomUUID().toString();var frame=put(m,task,effect,session,1,"after",0,Color.BLUE,artifact,1);m.learn(task,frame.getString("id"),artifact(artifact,1,true),null,new JSONArray());var reopened=new VisualMemory043(root);assertEquals(1,reopened.state().getJSONArray("patterns").length());assertThrows(IllegalArgumentException.class,()->put(reopened,task,effect,session,1,"after",0,Color.BLUE,artifact,1));assertEquals(frame.getString("sha256"),PerceptionStore.hash(reopened.original(frame.getString("id"))));}
}
